//! Integration tests for payment providers

use purl_lib::{Config, EvmConfig, PaymentMethod, SolanaConfig, PROVIDER_REGISTRY};

#[test]
fn test_provider_registry_is_initialized() {
    let registry = &*PROVIDER_REGISTRY;
    assert!(registry.find_provider("base").is_some());
    assert!(registry.find_provider("solana").is_some());
}

#[test]
fn test_find_provider_for_networks() {
    let registry = &*PROVIDER_REGISTRY;

    let test_cases = vec![
        ("ethereum", true),
        ("base", true),
        ("base-sepolia", true),
        ("solana", true),
        ("solana-devnet", true),
        ("xx-unknown", false),
    ];

    for (network, should_exist) in test_cases {
        assert_eq!(
            registry.find_provider(network).is_some(),
            should_exist,
            "Provider for network {} should {}",
            network,
            if should_exist { "exist" } else { "not exist" }
        );
    }
}

#[test]
fn test_provider_not_found_for_unknown_network() {
    let registry = &*PROVIDER_REGISTRY;

    let test_cases = vec!["unknown-network", "bitcoin", ""];

    for network in test_cases {
        assert!(
            registry.find_provider(network).is_none(),
            "Provider for unknown network '{network}' should not exist"
        );
    }
}

#[test]
fn test_provider_names() {
    let registry = &*PROVIDER_REGISTRY;

    let test_cases = vec![("base", "EVM"), ("solana", "Solana")];

    for (network, expected_name) in test_cases {
        let provider = registry
            .find_provider(network)
            .unwrap_or_else(|| panic!("Should find {network} provider"));

        assert_eq!(
            provider.name(),
            expected_name,
            "Provider for network {network} should have name {expected_name}"
        );
    }
}

#[test]
fn test_validate_empty_config() {
    let config = Config {
        evm: None,
        solana: None,
        ..Default::default()
    };

    // Empty config should be valid (no wallets configured is OK)
    let result = config.validate();
    assert!(result.is_ok());
}

#[test]
fn test_validate_evm_config_keystore() {
    // Config without keystore should be valid (no wallet configured)
    let config = Config {
        evm: Some(EvmConfig { keystore: None }),
        solana: None,
        ..Default::default()
    };
    assert!(
        config.validate().is_ok(),
        "EVM config without keystore should be valid"
    );

    // Config with non-existent keystore should be invalid
    let config_with_bad_keystore = Config {
        evm: Some(EvmConfig {
            keystore: Some(std::path::PathBuf::from("/nonexistent/keystore.json")),
        }),
        solana: None,
        ..Default::default()
    };
    assert!(
        config_with_bad_keystore.validate().is_err(),
        "EVM config with non-existent keystore should be invalid"
    );
}

#[test]
fn test_validate_both_configs_without_keystores() {
    // Config with both EVM and Solana sections but no keystores should be valid
    let config = Config {
        evm: Some(EvmConfig { keystore: None }),
        solana: Some(SolanaConfig { keystore: None }),
        ..Default::default()
    };

    // This should be valid - no keystores configured
    assert!(config.validate().is_ok());
}

#[test]
fn test_provider_supports_correct_networks() {
    let registry = &*PROVIDER_REGISTRY;

    let evm_provider = registry.find_provider("base").unwrap();
    let evm_test_cases = vec![("base", true), ("ethereum", true), ("solana", false)];

    for (network, should_support) in evm_test_cases {
        assert_eq!(
            evm_provider.supports_network(network),
            should_support,
            "EVM provider should {} support network {}",
            if should_support { "" } else { "not" },
            network
        );
    }

    let solana_provider = registry.find_provider("solana").unwrap();
    let solana_test_cases = vec![("solana", true), ("solana-devnet", true), ("base", false)];

    for (network, should_support) in solana_test_cases {
        assert_eq!(
            solana_provider.supports_network(network),
            should_support,
            "Solana provider should {} support network {}",
            if should_support { "" } else { "not" },
            network
        );
    }
}

#[test]
fn test_find_provider_is_case_sensitive() {
    let registry = &*PROVIDER_REGISTRY;

    let test_cases = vec![("base", true), ("BASE", false), ("Base", false)];

    for (network, should_exist) in test_cases {
        assert_eq!(
            registry.find_provider(network).is_some(),
            should_exist,
            "Provider lookup for '{}' should {} (case-sensitive)",
            network,
            if should_exist { "succeed" } else { "fail" }
        );
    }
}

#[test]
fn test_multiple_providers_dont_conflict() {
    let registry = &*PROVIDER_REGISTRY;

    let evm = registry.find_provider("base");
    let solana = registry.find_provider("solana");

    assert!(evm.is_some());
    assert!(solana.is_some());
    assert_ne!(evm.unwrap().name(), solana.unwrap().name());
}

#[test]
fn test_find_tempo_provider() {
    let registry = &*PROVIDER_REGISTRY;

    let provider = registry.find_provider("tempo");
    assert!(provider.is_some());
    assert_eq!(provider.unwrap().name(), "Tempo");

    let provider = registry.find_provider("tempo-moderato");
    assert!(provider.is_some());
    assert_eq!(provider.unwrap().name(), "Tempo");
}

#[test]
fn test_find_tempo_provider_via_alias() {
    let registry = &*PROVIDER_REGISTRY;

    let provider = registry.find_provider("eip155:4217");
    assert!(provider.is_some());
    assert_eq!(provider.unwrap().name(), "Tempo");

    let provider = registry.find_provider("eip155:42431");
    assert!(provider.is_some());
    assert_eq!(provider.unwrap().name(), "Tempo");
}

#[test]
fn test_tempo_provider_does_not_handle_evm_networks() {
    let registry = &*PROVIDER_REGISTRY;

    let tempo = registry.find_provider("tempo").unwrap();

    assert!(!tempo.supports_network("base"));
    assert!(!tempo.supports_network("ethereum"));
    assert!(!tempo.supports_network("solana"));
    assert!(tempo.supports_network("tempo"));
    assert!(tempo.supports_network("tempo-moderato"));
}

#[test]
fn test_all_three_providers_distinct() {
    let registry = &*PROVIDER_REGISTRY;

    let evm = registry.find_provider("base").unwrap();
    let solana = registry.find_provider("solana").unwrap();
    let tempo = registry.find_provider("tempo-moderato").unwrap();

    assert_ne!(evm.name(), solana.name());
    assert_ne!(evm.name(), tempo.name());
    assert_ne!(solana.name(), tempo.name());
}

#[test]
fn test_payment_method_tempo() {
    assert_eq!(PaymentMethod::Tempo.as_str(), "tempo");
    assert_eq!(PaymentMethod::Tempo.display_name(), "Tempo");
    assert_eq!(format!("{}", PaymentMethod::Tempo), "Tempo");
}

//! File permission utilities for secure file operations.
//!
//! This module provides platform-specific functions to set restrictive
//! permissions on sensitive files like config and keystores.

use crate::error::Result;
use std::path::Path;

/// Set secure permissions on a file (0600 - owner read/write only).
#[cfg(unix)]
pub fn set_secure_file_permissions(path: &Path) -> Result<()> {
    use std::os::unix::fs::PermissionsExt;

    let permissions = std::fs::Permissions::from_mode(0o600);
    std::fs::set_permissions(path, permissions)?;
    Ok(())
}

/// No-op on non-Unix systems - rely on OS-level file protection.
#[cfg(not(unix))]
pub fn set_secure_file_permissions(_path: &Path) -> Result<()> {
    Ok(())
}

/// Set secure permissions on a directory (0700 - owner only).
#[cfg(unix)]
pub fn set_secure_dir_permissions(path: &Path) -> Result<()> {
    use std::os::unix::fs::PermissionsExt;

    let permissions = std::fs::Permissions::from_mode(0o700);
    std::fs::set_permissions(path, permissions)?;
    Ok(())
}

/// No-op on non-Unix systems - rely on OS-level file protection.
#[cfg(not(unix))]
pub fn set_secure_dir_permissions(_path: &Path) -> Result<()> {
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    #[cfg(unix)]
    fn test_set_secure_file_permissions() {
        use std::os::unix::fs::PermissionsExt;

        let temp_dir = TempDir::new().unwrap();
        let file_path = temp_dir.path().join("test_file");
        std::fs::write(&file_path, "test content").unwrap();

        set_secure_file_permissions(&file_path).unwrap();

        let metadata = std::fs::metadata(&file_path).unwrap();
        let mode = metadata.permissions().mode() & 0o777;
        assert_eq!(mode, 0o600);
    }

    #[test]
    #[cfg(unix)]
    fn test_set_secure_dir_permissions() {
        use std::os::unix::fs::PermissionsExt;

        let temp_dir = TempDir::new().unwrap();
        let dir_path = temp_dir.path().join("test_dir");
        std::fs::create_dir(&dir_path).unwrap();

        set_secure_dir_permissions(&dir_path).unwrap();

        let metadata = std::fs::metadata(&dir_path).unwrap();
        let mode = metadata.permissions().mode() & 0o777;
        assert_eq!(mode, 0o700);
    }
}

use purl_lib::x402::{v1, PaymentRequirements};

/// Helper to create a test payment requirement
fn create_test_requirement(max_amount: &str) -> PaymentRequirements {
    PaymentRequirements::V1(v1::PaymentRequirements {
        scheme: "eip3009".to_string(),
        network: "base".to_string(),
        max_amount_required: max_amount.to_string(),
        asset: "0x1234567890123456789012345678901234567891".to_string(),
        pay_to: "0x1234567890abcdef1234567890abcdef12345678".to_string(),
        resource: "/test".to_string(),
        description: "Test payment".to_string(),
        mime_type: "application/json".to_string(),
        output_schema: None,
        max_timeout_seconds: 300,
        extra: None,
    })
}

#[test]
fn test_max_amount_validation_logic() {
    let requirement = create_test_requirement("100000");

    let required: u128 = requirement.parse_max_amount().unwrap().as_atomic_units();

    let max_allowed: u128 = "200000".parse().unwrap();
    assert!(
        required <= max_allowed,
        "Payment should be allowed when max_amount >= required"
    );

    let max_allowed: u128 = "100000".parse().unwrap();
    assert!(
        required <= max_allowed,
        "Payment should be allowed when max_amount == required"
    );

    let max_allowed: u128 = "1".parse().unwrap();
    assert!(
        required > max_allowed,
        "Payment should be rejected when max_amount < required"
    );
}

#[test]
fn test_max_amount_validation_with_various_amounts() {
    struct TestCase {
        required: &'static str,
        max_allowed: &'static str,
        should_pass: bool,
        description: &'static str,
    }

    let test_cases = vec![
        TestCase {
            required: "100000",
            max_allowed: "1",
            should_pass: false,
            description: "Required amount much higher than max",
        },
        TestCase {
            required: "100000",
            max_allowed: "99999",
            should_pass: false,
            description: "Required amount slightly higher than max",
        },
        TestCase {
            required: "100000",
            max_allowed: "100000",
            should_pass: true,
            description: "Required amount equal to max",
        },
        TestCase {
            required: "100000",
            max_allowed: "100001",
            should_pass: true,
            description: "Required amount slightly lower than max",
        },
        TestCase {
            required: "100000",
            max_allowed: "1000000",
            should_pass: true,
            description: "Required amount much lower than max",
        },
        TestCase {
            required: "0",
            max_allowed: "0",
            should_pass: true,
            description: "Both amounts are zero",
        },
    ];

    for test_case in test_cases {
        let requirement = create_test_requirement(test_case.required);
        let required: u128 = requirement.parse_max_amount().unwrap().as_atomic_units();
        let max_allowed: u128 = test_case.max_allowed.parse().unwrap();

        let passes = required <= max_allowed;
        assert_eq!(
            passes, test_case.should_pass,
            "Test case '{}' failed: required={}, max_allowed={}",
            test_case.description, test_case.required, test_case.max_allowed
        );
    }
}

#[test]
fn test_max_amount_constraint_ordering() {
    let requirement = create_test_requirement("100000");
    let required: u128 = requirement.parse_max_amount().unwrap().as_atomic_units();
    let max_allowed: u128 = "1".parse().unwrap();

    let constraint_violated = required > max_allowed;

    assert!(
        constraint_violated,
        "Max amount constraint must be checked before any payment processing"
    );
}

//! Integration tests for HTTP client and builder

use purl_lib::HttpClientBuilder;

#[test]
fn test_http_client_builder_basic_builders() {
    let test_cases: Vec<Box<dyn Fn() -> HttpClientBuilder>> = vec![
        Box::new(HttpClientBuilder::default),
        Box::new(HttpClientBuilder::new),
        Box::new(|| HttpClientBuilder::new().verbose(true)),
        Box::new(|| HttpClientBuilder::new().timeout(30)),
        Box::new(|| HttpClientBuilder::new().follow_redirects(true)),
        Box::new(|| HttpClientBuilder::new().user_agent("TestAgent/1.0")),
        Box::new(|| HttpClientBuilder::new().header("X-Custom-Header", "custom-value")),
    ];

    for (i, builder_fn) in test_cases.iter().enumerate() {
        let builder = builder_fn();
        let client = builder.build();
        assert!(client.is_ok(), "Builder test case {i} should succeed");
    }
}

#[test]
fn test_http_client_builder_with_multiple_headers() {
    let headers = vec![
        ("X-Header-1".to_string(), "value1".to_string()),
        ("X-Header-2".to_string(), "value2".to_string()),
    ];
    let builder = HttpClientBuilder::new().headers(&headers);
    let client = builder.build();
    assert!(client.is_ok());
}

#[test]
fn test_http_client_builder_chained() {
