    let builder = HttpClientBuilder::new()
        .header(String::from("X-String"), String::from("string-value"))
        .header("X-Str", "str-value")
        .user_agent(String::from("StringAgent/1.0"));

    let client = builder.build();
    assert!(client.is_ok());
}

//! Regression tests for redirect handling of credential-bearing requests

use purl_lib::HttpClientBuilder;
use std::sync::{Arc, Mutex};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpListener;

/// Spawn a loopback server that answers every request with `response` and records
/// the raw request heads it receives.
async fn spawn_server(response: String) -> (String, Arc<Mutex<Vec<String>>>) {
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let requests = Arc::new(Mutex::new(Vec::new()));
    let recorded = requests.clone();
    tokio::spawn(async move {
        loop {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut buf = vec![0u8; 8192];
            let n = stream.read(&mut buf).await.unwrap();
            recorded
                .lock()
                .unwrap()
                .push(String::from_utf8_lossy(&buf[..n]).to_lowercase());
            stream.write_all(response.as_bytes()).await.unwrap();
            stream.shutdown().await.ok();
        }
    });
    (base, requests)
}

fn redirect_to(location: &str) -> String {
    format!(
        "HTTP/1.1 302 Found\r\nLocation: {location}\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
    )
}

const PAYMENT_REQUIRED: &str =
    "HTTP/1.1 402 Payment Required\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";

#[tokio::test]
async fn response_url_reports_redirect_destination() {
    let (payment_origin, _) = spawn_server(PAYMENT_REQUIRED.to_string()).await;
    let (redirector, _) = spawn_server(redirect_to(&format!("{payment_origin}/paid"))).await;

    let client = HttpClientBuilder::new()
        .follow_redirects(true)
        .build()
        .unwrap();
    let response = client.get(&format!("{redirector}/start")).await.unwrap();

    assert_eq!(response.status_code, 402);
    assert_eq!(response.url, format!("{payment_origin}/paid"));
}

#[tokio::test]
async fn same_origin_only_does_not_forward_credentials_cross_origin() {
    let (other_origin, other_requests) = spawn_server(PAYMENT_REQUIRED.to_string()).await;
    let (origin, _) = spawn_server(redirect_to(&format!("{other_origin}/steal"))).await;

    let client = HttpClientBuilder::new()
        .follow_redirects(true)
        .same_origin_redirects_only(true)
        .header("Payment-Signature", "secret-credential")
        .build()
        .unwrap();
    let response = client.get(&format!("{origin}/paid")).await.unwrap();

    assert_eq!(response.status_code, 302);
    assert_eq!(response.url, format!("{origin}/paid"));
    assert!(other_requests.lock().unwrap().is_empty());
}

#[tokio::test]
async fn same_origin_only_still_follows_same_origin_redirects() {
    // A server that always redirects to itself: following must continue until the
    // redirect limit is hit, proving same-origin redirects are honored.
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let hits = Arc::new(Mutex::new(0usize));
    let counter = hits.clone();
    let location = format!("{base}/loop");
    tokio::spawn(async move {
        loop {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut buf = vec![0u8; 8192];
            let _ = stream.read(&mut buf).await.unwrap();
            *counter.lock().unwrap() += 1;
            stream
                .write_all(redirect_to(&location).as_bytes())
                .await
                .unwrap();
            stream.shutdown().await.ok();
        }
    });

    let client = HttpClientBuilder::new()
        .follow_redirects(true)
        .same_origin_redirects_only(true)
        .build()
        .unwrap();
    let result = client.get(&format!("{base}/start")).await;

    assert!(result.is_err());
    assert!(*hits.lock().unwrap() > 1);
}

//! Integration tests for configuration management

use purl_lib::{Config, EvmConfig, PaymentMethod, SolanaConfig};

#[test]
fn test_config_serialization_roundtrip() {
    let config = Config {
        evm: Some(EvmConfig {
            keystore: Some(std::path::PathBuf::from("/path/to/evm.json")),
        }),
        solana: Some(SolanaConfig {
            keystore: Some(std::path::PathBuf::from("/path/to/solana.json")),
        }),
        ..Default::default()
    };

    let toml_str = toml::to_string_pretty(&config).expect("Failed to serialize");
    let deserialized: Config = toml::from_str(&toml_str).expect("Failed to deserialize");

    assert!(deserialized.evm.is_some());
    assert!(deserialized.solana.is_some());
    assert_eq!(
        deserialized.evm.as_ref().unwrap().keystore,
        config.evm.as_ref().unwrap().keystore
    );
    assert_eq!(
        deserialized.solana.as_ref().unwrap().keystore,
        config.solana.as_ref().unwrap().keystore
    );
}

#[test]
fn test_available_payment_methods() {
    struct TestCase {
        evm: Option<EvmConfig>,
        solana: Option<SolanaConfig>,
        expected_len: usize,
        should_contain_evm: bool,
        should_contain_solana: bool,
    }

    let test_cases = vec![
        TestCase {
            evm: Some(EvmConfig {
                keystore: Some(std::path::PathBuf::from("/path/to/evm.json")),
            }),
            solana: Some(SolanaConfig {
                keystore: Some(std::path::PathBuf::from("/path/to/solana.json")),
            }),
            expected_len: 2,
            should_contain_evm: true,
            should_contain_solana: true,
        },
        TestCase {
            evm: Some(EvmConfig {
                keystore: Some(std::path::PathBuf::from("/path/to/evm.json")),
            }),
            solana: None,
            expected_len: 1,
            should_contain_evm: true,
            should_contain_solana: false,
        },
        TestCase {
            evm: None,
            solana: Some(SolanaConfig {
                keystore: Some(std::path::PathBuf::from("/path/to/solana.json")),
            }),
            expected_len: 1,
            should_contain_evm: false,
            should_contain_solana: true,
        },
        TestCase {
            evm: None,
            solana: None,
            expected_len: 0,
            should_contain_evm: false,
            should_contain_solana: false,
        },
    ];

    for test_case in test_cases {
        let config = Config {
            evm: test_case.evm,
            solana: test_case.solana,
            ..Default::default()
        };

        let methods = config.available_payment_methods();
        assert_eq!(
            methods.len(),
            test_case.expected_len,
            "Expected {} payment methods",
            test_case.expected_len
        );
        assert_eq!(
            methods.contains(&PaymentMethod::Evm),
            test_case.should_contain_evm,
            "EVM method presence should be {}",
            test_case.should_contain_evm
        );
        assert_eq!(
            methods.contains(&PaymentMethod::Solana),
            test_case.should_contain_solana,
            "Solana method presence should be {}",
            test_case.should_contain_solana
        );
    }
}

#[test]
fn test_config_validation_evm_keystore() {
    // Config without keystore should be valid (no wallet configured)
    let config = Config {
        evm: Some(EvmConfig { keystore: None }),
        solana: None,
        ..Default::default()
    };
    assert!(
        config.validate().is_ok(),
        "EVM config without keystore should be valid"
    );

    // Config with non-existent keystore should fail validation
    let config_with_bad_keystore = Config {
        evm: Some(EvmConfig {
            keystore: Some(std::path::PathBuf::from("/nonexistent/keystore.json")),
        }),
        solana: None,
        ..Default::default()
    };
    assert!(
        config_with_bad_keystore.validate().is_err(),
        "EVM config with non-existent keystore should be invalid"
    );
}

#[test]
